examples.template:
Column {
    LazyColumn(
        modifier = Modifier.height(MonarchTheme.spacing.space24 * 3),
        state = state,
        reverseLayout = true,
    ) {
        items(count = {{count}}, key = { it }) { index ->
            MonarchListRow(headlineContent = { MonarchText(text = lines[({{count}} - 1 - index) % lines.size]) }, divider = true)
        }
    }
    if (!atBottom) {
        MonarchButton(
            text = {{jump}},
            size = MonarchButtonSize.Sm,
            onClick = { scope.launch { if (reduceMotion) state.scrollToItem(0) else state.animateScrollToItem(0) } },
        )
    }
}

